def main():
    plugin = Path(__file__).resolve().parents[2]
    source = plugin / 'android/src/main/java/com/cloudwebrtc/webrtc/video/camera/CameraCaptureControls.java'
    with tempfile.TemporaryDirectory(prefix='bshare-device-controls-') as directory:
        temp = Path(directory)
        for name, value in STUBS.items():
            path = temp / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(value)
        harness = temp / 'com/cloudwebrtc/webrtc/video/camera/CameraCaptureControlsTest.java'
        harness.parent.mkdir(parents=True, exist_ok=True)
        harness.write_text(HARNESS)
        java_home = os.environ.get('JAVA_HOME')
        candidates = [Path(java_home) / 'bin' if java_home else None,
                      Path('C:/Program Files/Android/Android Studio/jbr/bin')]
        java_bin = next((path for path in candidates if path and (path / 'javac.exe').exists()), None)
        javac = str(java_bin / 'javac.exe') if java_bin else 'javac'
        java = str(java_bin / 'java.exe') if java_bin else 'java'
        subprocess.run([javac, '-Xlint:none', '-d', str(temp), str(source),
                        *[str(temp / name) for name in STUBS], str(harness)], check=True)
        subprocess.run([java, '-ea', '-cp', str(temp),
                        'com.cloudwebrtc.webrtc.video.camera.CameraCaptureControlsTest'], check=True)

if __name__ == '__main__':
    main()
